    }));
  }
  const renamedUserConfigs = userConfigs.map((item) => {
    if (item.rules) {
      item.rules = renameRules(
        item.rules,
        { "@typescript-eslint": "ts" }
      );
    }
    return item;
  });
  let composer = new FlatConfigComposer();
  composer = composer.append(
    ...configs,
    ...renamedUserConfigs
  );
  return composer;
}

